# because the TranslatorFactory makes it superfluous.",snippet-only route,False,none,,planner_evidence,0,0,0,TranslatorFactory,TranslatorFactory,,1,"[{""method_name"": ""TranslatorFactory"", ""path"": ""manila/openstack/common/gettextutils.py"", ""class_name"": null, ""start_line"": 41, ""end_line"": 115, ""source"": ""class TranslatorFactory(object):
    """"""Create translator functions
    """"""

    def __init__(self, domain, lazy=False, localedir=None):
        """"""Establish a set of translation functions for the domain.

        :param domain: Name of translation domain,
                       specifying a message catalog.
        :type domain: str
        :param lazy: Delays translation until a message is emitted.
                     Defaults to False.
        :type lazy: Boolean
        :param localedir: Directory with translation catalogs.
        :type localedir: str
        """"""
        self.domain = domain
        self.lazy = lazy
        if localedir is None:
            localedir = os.environ.get(domain.upper() + '_LOCALEDIR')
        self.localedir = localedir

    def _make_translation_func(self, domain=None):
        """"""Return a new translation function ready for use.

        Takes into account whether or not lazy translation is being
        done.

        The domain can be specified to override the default from the
        factory, but the localedir from the factory is always used
        because we assume the log-level translation catalogs are
        installed in the same directory as the main application
        catalog.

        """"""
        if domain is None:
            domain = self.domain
        if self.lazy:
            return functools.partial(Message, domain=domain)
        t = gettext.translation(
            domain,
            localedir=self.localedir,
            fallback=True,
        )
        if six.PY3:
            return t.gettext
        return t.ugettext

    @property
    def primary(self):
        ""The default translation function.""
        return self._make_translation_func()

    def _make_log_translation_func(self, level):
        return self._make_translation_func(self.domain + '-log-' + level)

    @property
    def log_info(self):
        ""Translate info-level log messages.""
        return self._make_log_translation_func('info')

    @property
    def log_warning(self):
        ""Translate warning-level log messages.""
        return self._make_log_translation_func('warning')

    @property
    def log_error(self):
        ""Translate error-level log messages.""
        return self._make_log_translation_func('error')

    @property
    def log_critical(self):
        ""Translate critical-level log messages.""
        return self._make_log_translation_func('critical')"", ""found"": true, ""signature"": """", ""callsite_slice"": """", ""evidence_slice"": """", ""match_score"": 0, ""confidence"": 0.0, ""confidence_label"": """"}]",[],[],True,skipped_fixer_only,"def enable_lazy():

